  q(AGE,'Which test assesses an older adult’s leg strength by standing up from a chair?','30-second chair stand',['Six-minute run test','Manual dexterity test','Peak flow test'],'A','Fewer stands than expected for age suggests higher fall risk.',PF),
  q(AGE,'Which play activity helps a toddler build balance?','Walking on a low balance beam',['Watching cartoons all day','Sitting in a car seat','Coloring at a table'],'B','Play-based therapy keeps children engaged while building motor skills.',PAG)
